const mysql = require\(''mysql2/promise''\);

async function testDashboardData\(\) {
  const conn = await mysql.createConnection\({
    host: ''rm-bp1k2s5b10qh2rw679o.mysql.rds.aliyuncs.com'',
    port: 3306,
    user: ''baboontalkies'',
    password: ''Kiki101422!'',
    database: ''baboontalkies''
  }\);

  // 模拟 dashboard-data API 的查询逻辑
  const [allCardData] = await conn.execute\(\\`
    SELECT
      student as name,
      mobile,
      class_card_type as courseType,
      card_times_left as remainingClasses,
      arranged_times as scheduledClasses
    FROM yuekebao_student_cardnum
    WHERE time_num > 0
    ORDER BY student
  \\`\);

  console.log\(''=== 总记录数 ===''\);
  console.log\(allCardData.length\);

  // 搜索Ray
  const rayRecords = allCardData.filter\(r => r.name && r.name.includes\(''Ray''\)\);
  console.log\(''\\n=== Ray相关记录 ===''\);
  console.log\(JSON.stringify\(rayRecords, null, 2\)\);

  // 模拟过滤逻辑
  const studentCardMap = new Map\(\);
  allCardData.forEach\(card => {
    const studentName = card.name;
    if \(!studentCardMap.has\(studentName\)\) {
      studentCardMap.set\(studentName, []\);
    }
    studentCardMap.get\(studentName\).push\(card\);
  }\);

  const cardData = [];
  studentCardMap.forEach\(\(cards, studentName\) => {
    if \(cards.length === 1\) {
      cardData.push\(cards[0]\);
    } else {
      const validCards = cards.filter\(card => card.remainingClasses > 0\);
      cardData.push\(...validCards\);
    }
  }\);

  const rayFiltered = cardData.filter\(r => r.name && r.name.includes\(''Ray''\)\);
  console.log\(''\\n=== 过滤后Ray相关记录 ===''\);
  console.log\(JSON.stringify\(rayFiltered, null, 2\)\);

  await conn.end\(\);
}

testDashboardData\(\).catch\(console.error\);
")

